1	#!/usr/bin/env node
2	/**
3	 * Node.js port of dataset/boltons/test6.py.
4	 *
5	 * Mirrors the original one-for-one: three required string options parsed with
6	 * argparse, then an OrderedMultiDict exercised through add/getlist/keys/items.
7	 */
8	
9	import { ArgumentParser } from './lib/argparse/index.mjs';
10	import { SystemExit } from './lib/argparse/errors.mjs';
11	import { OMD } from './lib/dictutils/index.mjs';
12	import { list, print, pyStr } from './lib/py/builtins.mjs';
13	
14	function main() {
15	  const parser = new ArgumentParser();
16	  parser.addArgument('--a', { type: pyStr, required: true });
17	  parser.addArgument('--b', { type: pyStr, required: true });
18	  parser.addArgument('--c', { type: pyStr, required: true });
19	  const args = parser.parseArgs();
20	
21	  const omd = new OMD(); // 创建有序多值字典
22	  print(omd);
23	  omd.add(args.a, args.b); // 添加键值对（add方法返回None）
24	  print(omd);
25	  omd.add(args.a, args.c); // 添加相同键的第二个值
26	  print(omd);
27	  const result1 = omd.getlist(args.a); // 获取键的所有值
28	  print(result1);
29	  const result2 = list(omd.keys()); // 获取所有键
30	  print(result2);
31	  const result3 = list(omd.items()); // 获取所有键值对
32	  print(result3);
33	}
34	
35	try {
36	  main();
37	} catch (error) {
38	  // argparse signals --help and usage errors the way CPython raises SystemExit.
39	  if (error instanceof SystemExit) process.exit(error.code);
40	  throw error;
41	}
42

1	/**
2	 * Python `repr()` / `str()` reproduction for the value shapes this program
3	 * prints: `str`, `list` and `tuple`.
4	 */
5	
6	import { codePointsOf, hex, isPrintableCodePoint } from './unicode.mjs';
7	
8	/**
9	 * Faithful port of CPython's `unicode_repr()`.
10	 *
11	 * Quote selection: single quotes normally; double quotes when the string
12	 * contains a single quote but no double quote (so nothing needs escaping).
13	 * Then, per code point:
14	 *   - the active quote and backslash are backslash-escaped
15	 *   - \t, \n, \r get their short form
16	 *   - other C0 controls and U+007F become \xhh
17	 *   - printable code points are emitted literally
18	 *   - remaining non-printables become \xhh, \uhhhh or \UHHHHHHHH
19	 */
20	export function reprStr(text) {
21	  const quote = text.includes("'") && !text.includes('"') ? '"' : "'";
22	  let out = quote;
23	  for (const [ch, cp] of codePointsOf(text)) {
24	    if (ch === quote || ch === '\\') out += '\\' + ch;
25	    else if (ch === '\t') out += '\\t';
26	    else if (ch === '\n') out += '\\n';
27	    else if (ch === '\r') out += '\\r';
28	    else if (cp < 0x20 || cp === 0x7f) out += '\\x' + hex(cp, 2);
29	    else if (cp < 0x7f) out += ch;
30	    else if (isPrintableCodePoint(cp)) out += ch;
31	    else if (cp <= 0xff) out += '\\x' + hex(cp, 2);
32	    else if (cp <= 0xffff) out += '\\u' + hex(cp, 4);
33	    else out += '\\U' + hex(cp, 8);
34	  }
35	  return out + quote;
36	}
37	
38	/**
39	 * A Python tuple. Needed as a distinct type because `repr` renders it with
40	 * parentheses and appends a trailing comma when it holds a single item.
41	 */
42	export class PyTuple {
43	  constructor(items) {
44	    this.items = items;
45	  }
46	  get length() {
47	    return this.items.length;
48	  }
49	  [Symbol.iterator]() {
50	    return this.items[Symbol.iterator]();
51	  }
52	}
53	
54	export function tuple(...items) {
55	  return new PyTuple(items);
56	}
57	
58	/** Marker interface: any object exposing `__repr__()` renders through it. */
59	export function repr(value) {
60	  if (typeof value === 'string') return reprStr(value);
61	  if (value === null || value === undefined) return 'None';
62	  if (value === true) return 'True';
63	  if (value === false) return 'False';
64	  if (value instanceof PyTuple) {
65	    if (value.items.length === 1) return '(' + repr(value.items[0]) + ',)';
66	    return '(' + value.items.map(repr).join(', ') + ')';
67	  }
68	  if (Array.isArray(value)) {
69	    return '[' + value.map(repr).join(', ') + ']';
70	  }
71	  if (typeof value === 'object' && typeof value.__repr__ === 'function') {
72	    return value.__repr__();
73	  }
74	  if (typeof value === 'number') return reprNumber(value);
75	  return String(value);
76	}
77	
78	/** `str()` falls back to `repr()` for containers, as in Python. */
79	export function str(value) {
80	  if (typeof value === 'string') return value;
81	  if (typeof value === 'object' && value !== null && typeof value.__str__ === 'function') {
82	    return value.__str__();
83	  }
84	  return repr(value);
85	}
86	
87	/** Minimal `repr` for numbers (integers print without a trailing ".0"). */
88	function reprNumber(value) {
89	  if (Number.isInteger(value) && Object.is(value, Math.trunc(value))) {
90	    return String(value);
91	  }
92	  return String(value);
93	}
94

1	/**
2	 * `OrderedMultiDict` (alias `OMD`) -- an insertion-ordered mapping that keeps
3	 * every value added for a key.
4	 *
5	 * Behaviour reproduced from observing the reference implementation:
6	 *   - `add(k, v)` appends a value and returns nothing.
7	 *   - `keys()` yields each distinct key once, in order of first insertion.
8	 *   - `getlist(k)` yields every value stored for `k`, in insertion order.
9	 *   - `items()` yields one pair per distinct key holding that key's *last*
10	 *     value; `items(true)` yields every (key, value) pair in insertion order.
11	 *   - `repr()` renders as `OrderedMultiDict([...])` over the full multi-value
12	 *     pair list, so a repeated key shows up more than once.
13	 *
14	 * Internally a per-key value list gives O(1) `getlist`, while a parallel pair
15	 * list preserves the exact interleaving needed for multi-value iteration.
16	 */
17	
18	import { PyTuple, repr } from '../py/repr.mjs';
19	import { keyToken } from './keys.mjs';
20	
21	export class OrderedMultiDict {
22	  /**
23	   * @param {Iterable<[any, any]>|OrderedMultiDict|null} initial optional
24	   *   initial pairs, applied in order via `addlist` semantics.
25	   */
26	  constructor(initial = null) {
27	    /** @type {Map<any, {key: any, values: any[]}>} first-insertion ordered */
28	    this._slots = new Map();
29	    /** @type {Array<[any, any]>} every pair, in insertion order */
30	    this._pairs = [];
31	    if (initial !== null && initial !== undefined) {
32	      this.updateExtend(initial);
33	    }
34	  }
35	
36	  // ------------------------------------------------------------------ writing
37	
38	  /** `omd.add(key, value)` -- append a value for `key`. Returns undefined. */
39	  add(key, value) {
40	    const token = keyToken(key);
41	    let slot = this._slots.get(token);
42	    if (slot === undefined) {
43	      slot = { key, values: [] };
44	      this._slots.set(token, slot);
45	    }
46	    slot.values.push(value);
47	    this._pairs.push([slot.key, value]);
48	  }
49	
50	  /** `omd.addlist(key, values)` -- append several values for `key`. */
51	  addlist(key, values) {
52	    for (const value of values) this.add(key, value);
53	  }
54	
55	  /** `omd[key] = value` -- discard existing values, keep only `value`. */
56	  setitem(key, value) {
57	    this.popall(key, null);
58	    this.add(key, value);
59	  }
60	
61	  /** `del omd[key]` -- remove the key and every value stored for it. */
62	  delitem(key) {
63	    const token = keyToken(key);
64	    if (!this._slots.has(token)) throw new Error(`KeyError: ${repr(key)}`);
65	    this._slots.delete(token);
66	    this._pairs = this._pairs.filter(([pairKey]) => keyToken(pairKey) !== token);
67	  }
68	
69	  /** Remove `key`, returning its last value (or `fallback`). */
70	  pop(key, fallback = undefined) {
71	    const token = keyToken(key);
72	    const slot = this._slots.get(token);
73	    if (slot === undefined) {
74	      if (fallback === undefined) throw new Error(`KeyError: ${repr(key)}`);
75	      return fallback;
76	    }
77	    const last = slot.values[slot.values.length - 1];
78	    this.delitem(key);
79	    return last;
80	  }
81	
82	  /** Remove `key`, returning every value stored for it (or `fallback`). */
83	  popall(key, fallback = undefined) {
84	    const token = keyToken(key);
85	    const slot = this._slots.get(token);
86	    if (slot === undefined) {
87	      if (fallback === undefined) throw new Error(`KeyError: ${repr(key)}`);
88	      return fallback;
89	    }
90	    const values = [...slot.values];
91	    this.delitem(key);
92	    return values;
93	  }
94	
95	  /** Merge another mapping, replacing values for keys already present. */
96	  update(other) {
97	    for (const [key, value] of pairsOf(other)) this.setitem(key, value);
98	  }
99	
100	  /** Merge another mapping, appending values for keys already present. */
101	  updateExtend(other) {
102	    for (const [key, value] of pairsOf(other)) this.add(key, value);
103	  }
104	
105	  clear() {
106	    this._slots.clear();
107	    this._pairs = [];
108	  }
109	
110	  // ------------------------------------------------------------------ reading
111	
112	  /** `omd[key]` -- the last value stored for `key`. */
113	  getitem(key) {
114	    const slot = this._slots.get(keyToken(key));
115	    if (slot === undefined) throw new Error(`KeyError: ${repr(key)}`);
116	    return slot.values[slot.values.length - 1];
117	  }
118	
119	  /** `omd.get(key, default)` -- the last value stored for `key`. */
120	  get(key, fallback = null) {
121	    const slot = this._slots.get(keyToken(key));
122	    if (slot === undefined) return fallback;
123	    return slot.values[slot.values.length - 1];
124	  }
125	
126	  /** `omd.getlist(key)` -- every value stored for `key`, in order. */
127	  getlist(key, fallback = null) {
128	    const slot = this._slots.get(keyToken(key));
129	    if (slot === undefined) return fallback === null ? [] : fallback;
130	    return [...slot.values];
131	  }
132	
133	  has(key) {
134	    return this._slots.has(keyToken(key));
135	  }
136	
137	  /** `omd.keys()` -- each distinct key once, in first-insertion order. */
138	  keys() {
139	    const result = [];
140	    for (const slot of this._slots.values()) result.push(slot.key);
141	    return result;
142	  }
143	
144	  /**
145	   * `omd.values(multi=False)` -- the last value per distinct key.
146	   * With `multi` true, every value in insertion order.
147	   */
148	  values(multi = false) {
149	    if (multi) return this._pairs.map(([, value]) => value);
150	    const result = [];
151	    for (const slot of this._slots.values()) result.push(slot.values[slot.values.length - 1]);
152	    return result;
153	  }
154	
155	  /**
156	   * `omd.items(multi=False)` -- one `(key, last value)` pair per distinct key.
157	   * With `multi` true, every `(key, value)` pair in insertion order.
158	   */
159	  items(multi = false) {
160	    if (multi) return this._pairs.map(([key, value]) => new PyTuple([key, value]));
161	    const result = [];
162	    for (const slot of this._slots.values()) {
163	      result.push(new PyTuple([slot.key, slot.values[slot.values.length - 1]]));
164	    }
165	    return result;
166	  }
167	
168	  /** Plain-object projection, mirroring `omd.todict()`. */
169	  todict(multi = false) {
170	    const result = new Map();
171	    for (const slot of this._slots.values()) {
172	      result.set(slot.key, multi ? [...slot.values] : slot.values[slot.values.length - 1]);
173	    }
174	    return result;
175	  }
176	
177	  /** Number of values stored for `key`. */
178	  countOf(key) {
179	    const slot = this._slots.get(keyToken(key));
180	    return slot === undefined ? 0 : slot.values.length;
181	  }
182	
183	  /** A shallow copy preserving all values and their order. */
184	  copy() {
185	    const clone = new this.constructor();
186	    for (const [key, value] of this._pairs) clone.add(key, value);
187	    return clone;
188	  }
189	
190	  /** `inverted()` -- values become keys and vice versa. */
191	  inverted() {
192	    const result = new this.constructor();
193	    for (const [key, value] of this._pairs) result.add(value, key);
194	    return result;
195	  }
196	
197	  /** `len(omd)` -- the number of distinct keys. */
198	  __len__() {
199	    return this._slots.size;
200	  }
201	
202	  get size() {
203	    return this._slots.size;
204	  }
205	
206	  /** Iterating an OMD yields its distinct keys, as with a Python mapping. */
207	  *[Symbol.iterator]() {
208	    for (const slot of this._slots.values()) yield slot.key;
209	  }
210	
211	  *iterkeys() {
212	    yield* this[Symbol.iterator]();
213	  }
214	
215	  *iteritems(multi = false) {
216	    yield* this.items(multi);
217	  }
218	
219	  *itervalues(multi = false) {
220	    yield* this.values(multi);
221	  }
222	
223	  /** Equal when both hold the same multi-value pair sequence. */
224	  equals(other) {
225	    if (!(other instanceof OrderedMultiDict)) return false;
226	    if (this._pairs.length !== other._pairs.length) return false;
227	    for (let i = 0; i < this._pairs.length; i += 1) {
228	      if (keyToken(this._pairs[i][0]) !== keyToken(other._pairs[i][0])) return false;
229	      if (this._pairs[i][1] !== other._pairs[i][1]) return false;
230	    }
231	    return true;
232	  }
233	
234	  /** `repr(omd)` -- e.g. `OrderedMultiDict([('a', 1), ('a', 2)])`. */
235	  __repr__() {
236	    const className = this.constructor.name;
237	    const body = this._pairs.map(([key, value]) => repr(new PyTuple([key, value]))).join(', ');
238	    return `${className}([${body}])`;
239	  }
240	
241	  /** `str(omd)` falls through to `repr(omd)`, as in Python. */
242	  __str__() {
243	    return this.__repr__();
244	  }
245	}
246	
247	/** Normalise anything mapping-like into an iterable of pairs. */
248	function pairsOf(source) {
249	  if (source instanceof OrderedMultiDict) return source._pairs.map(([k, v]) => [k, v]);
250	  if (source instanceof Map) return [...source.entries()];
251	  if (Array.isArray(source)) return source.map((pair) => [pair[0], pair[1]]);
252	  if (source && typeof source[Symbol.iterator] === 'function') {
253	    return [...source].map((pair) => [pair[0], pair[1]]);
254	  }
255	  return Object.entries(source ?? {});
256	}
257	
258	/** boltons exposes the short alias too. */
259	export const OMD = OrderedMultiDict;
260

1	/**
2	 * Unicode helpers mirroring CPython's notion of "printable".
3	 *
4	 * CPython's `Py_UNICODE_ISPRINTABLE` (used by `str.__repr__` and
5	 * `str.isprintable`) treats a code point as non-printable when its Unicode
6	 * General_Category is one of Cc, Cf, Cs, Co, Cn, Zl, Zp or Zs -- with the
7	 * single exception of U+0020 SPACE, which is always printable.
8	 *
9	 * We reproduce that with ECMAScript Unicode property escapes, which are a
10	 * native RegExp feature (no dependencies involved).
11	 */
12	
13	const NONPRINTABLE_CATEGORIES =
14	  /^[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]$/u;
15	
16	/** Lowest and highest UTF-16 surrogate code points. */
17	export const SURROGATE_MIN = 0xd800;
18	export const SURROGATE_MAX = 0xdfff;
19	
20	/** True when `cp` is a lone/paired surrogate code point (category Cs). */
21	export function isSurrogate(cp) {
22	  return cp >= SURROGATE_MIN && cp <= SURROGATE_MAX;
23	}
24	
25	/**
26	 * Equivalent of CPython's `Py_UNICODE_ISPRINTABLE` for a single code point.
27	 */
28	export function isPrintableCodePoint(cp) {
29	  if (cp === 0x20) return true; // SPACE is printable even though it is Zs
30	  if (isSurrogate(cp)) return false; // String.fromCodePoint would lose these
31	  return !NONPRINTABLE_CATEGORIES.test(String.fromCodePoint(cp));
32	}
33	
34	/**
35	 * Iterate a JS string by code point, the way Python iterates a `str`.
36	 *
37	 * The built-in string iterator already yields astral characters as a single
38	 * item and unpaired surrogates on their own, which matches Python's model of
39	 * a string as a sequence of code points (including the lone surrogates that
40	 * `surrogateescape` decoding can produce).
41	 */
42	export function* codePointsOf(text) {
43	  for (const ch of text) yield [ch, ch.codePointAt(0)];
44	}
45	
46	/** Zero-padded lowercase hex, as used by Python's escape sequences. */
47	export function hex(cp, width) {
48	  return cp.toString(16).padStart(width, '0');
49	}
50

1	/**
2	 * Key identity following Python's dict/hash rules, so that a ported mapping
3	 * groups keys the same way CPython would.
4	 *
5	 * Notably `True == 1 == 1.0` collide into one slot, and the *first* key object
6	 * inserted is the one the mapping keeps and reports back.
7	 */
8	
9	/**
10	 * Reduce a key to a token that compares equal exactly when Python would treat
11	 * the two keys as the same dict key. Non-primitive keys fall back to identity.
12	 */
13	export function keyToken(key) {
14	  if (key === null || key === undefined) return 'None';
15	  const type = typeof key;
16	  if (type === 'string') return 's�' + key;
17	  if (type === 'boolean') return 'n�' + (key ? '1' : '0');
18	  if (type === 'number') {
19	    // Python: hash(1) == hash(1.0); -0.0 == 0.0
20	    if (Number.isNaN(key)) return 'nan�';
21	    const normalized = key === 0 ? 0 : key;
22	    return 'n�' + String(normalized);
23	  }
24	  if (type === 'bigint') return 'n�' + key.toString();
25	  return key; // identity semantics for objects
26	}
27

1	/**
2	 * Small Python builtins used by the ported program.
3	 */
4	
5	export { print, writeStderr, writeStdout, exit } from './io.mjs';
6	export { repr, str, PyTuple, tuple, reprStr } from './repr.mjs';
7	
8	/** Python's `list(iterable)`: materialise an iterator into a sequence. */
9	export function list(iterable) {
10	  if (iterable === null || iterable === undefined) return [];
11	  return Array.from(iterable);
12	}
13	
14	/** Python's `len(obj)`. */
15	export function len(obj) {
16	  if (obj === null || obj === undefined) throw new TypeError('object has no len()');
17	  if (typeof obj === 'string' || Array.isArray(obj)) return obj.length;
18	  if (typeof obj.__len__ === 'function') return obj.__len__();
19	  if (typeof obj.length === 'number') return obj.length;
20	  if (typeof obj.size === 'number') return obj.size;
21	  throw new TypeError('object has no len()');
22	}
23	
24	/** Python's `str` type callable, as used for `type=str` in argparse. */
25	export function pyStr(value) {
26	  return typeof value === 'string' ? value : String(value);
27	}
28	// argparse renders the callable's name in "invalid <name> value" messages.
29	Object.defineProperty(pyStr, 'name', { value: 'str' });
30

