#!/bin/bash
# Randomised differential fuzz over an interesting character pool.
export LC_ALL=C.UTF-8
N=${1:-150}
SEED=${2:-1}
RANDOM=$SEED

POOL=( "'" '"' '\' $'\t' $'\n' $'\r' ' ' 'a' 'Z' '0' '9' '.' '-' '_' '(' ')' '[' ']' ',' ':' '{' '}' '=' '#'
       $'\x01' $'\x07' $'\x0b' $'\x0c' $'\x1b' $'\x7f' $'' $' ' $'ÿ' $'́' $' '
       $' ' $'​' $'‎' $'‮' $'⁠' $'﻿' $'￿' $'' $'\U0001f600'
       $'\U0001d7ff' $'\U000e0100' $'\U0010ffff' $'é' $'İ' 'True' 'None' 'False' '1.5' 'nan'
       "\\n" "\\'" '\\"' "', '" "')]" "OrderedMultiDict([" $'' $'᠎' $'　' $'﷐' )
P=${#POOL[@]}

rnd(){ # $1 = max length -> random string
  local len=$(( RANDOM % ($1+1) )) s="" i
  for ((i=0;i<len;i++)); do s+="${POOL[RANDOM % P]}"; done
  printf '%s' "$s"
}

fail=0
for ((k=0;k<N;k++)); do
  case $((RANDOM % 6)) in
    0) A=$(rnd 6); B=$A; C=$A;;
    1) A=$(rnd 6); B=$(rnd 6); C=$B;;
    2) A=""; B=$(rnd 8); C=$(rnd 8);;
    3) A=$(rnd 8); B=""; C="";;
    4) A=$(rnd 20); B=$(rnd 20); C=$(rnd 20);;
    5) A=$(rnd 4); B=$(rnd 40); C=$(rnd 40);;
  esac
  out=$(env -u LC_ALL -u LC_CTYPE /tmp/dt.sh --a "$A" --b "$B" --c "$C" 2>&1)
  if [ "$out" != "PASS" ]; then
    fail=$((fail+1))
    echo "=== RANDFAIL seed=$SEED k=$k ==="
    printf 'Ahex=%s\nBhex=%s\nChex=%s\n' "$(printf %s "$A"|od -An -tx1|tr -d ' \n')" "$(printf %s "$B"|od -An -tx1|tr -d ' \n')" "$(printf %s "$C"|od -An -tx1|tr -d ' \n')"
    echo "$out" | head -30
  fi
done
echo "RAND seed=$SEED TOTAL=$N FAILED=$fail"
